/// <summary>
/// AVA FormControl AVAWorkerSalesTaker
/// </summary>
[ExtensionOf(formControlStr(SalesTableListPage, AVADlvResponsible))]
final class AVASalesTableListPageFrmCtr_AVADlvResponsible_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret = next modified();

    FormDataSource avaSalesTable_ds = this.formRun().dataSource(tableStr(SalesTable));
    SalesTaker dlvResponsibleLoc = this.value();

    if (dlvResponsibleLoc)
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, AVADlvResponsible)).value(queryValue(dlvResponsibleLoc));
    }
    else
    {
        SysQuery::findOrCreateRange(avaSalesTable_ds.queryBuildDataSource(), fieldNum(SalesTable, AVADlvResponsible)).value(SysQueryRangeUtil::valueUnlimited());
    }

    avaSalesTable_ds.executeQuery();

    return ret;
}
